insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('dea-rennd-mit-an-hianpecka-duach-de-geegnd-dassd-glaubsd-dem-haums-des-letzde-resthian-aussegfressn', 'Dea rennd mit an Hianpecka duach de Geegnd, dassd glaubsd, dem haums des letzde Resthian aussegfressn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der rennt mit einem Hirnpecker durch die Gegend, dass du glaubst, dem haben sie das letzte Resthirn rausgefressen!', '[{"kategorie": "wörtlich", "text": "\"Der läuft wie ein Irrer durch die Gegend, als hätt'' er ''nen Specht im Kopf, der ihm das letzte Resthirn rauspickt!\"  2. Der rennt mit einer Vollmeise rum, als hätt'' man ihm das letzte Resthirn rausgehämmert!  3. Der Typ hat ''nen Dauerpecker im Hirn – der läuft rum wie’n aufgescheuchter Vollidiot, dem man das letzte Hirn rausgefressen hat!"}]'::jsonb, ''),
  ('an-hianpecka-haum', 'an Hianpecka haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Hirnpecker haben', '[{"kategorie": "wörtlich", "text": "\"einen geistigen Schaden haben\""}, {"kategorie": "", "text": "\"eine Vollmeise haben\""}, {"kategorie": "", "text": "\"einen Dachschaden haben\""}, {"kategorie": "", "text": "\"einen Sprung in der Schüssel haben\""}]'::jsonb, 'Hädad I so an Hianpecka wia dea, daunn däd I mi riseikln lossn!'),
  ('haedad-i-so-an-hianpecka-wia-dea-daunn-daed-i-mi-riseikln-lossn', 'Hädad I so an Hianpecka wia dea, daunn däd I mi riseikln lossn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hätte ich so einen Hirnpecker wie der, dann tät ich mich recyclen lassen!', '[{"kategorie": "wörtlich", "text": "\"Hätte ich eine solche Vollmeise wie der, würd ich mich recyclen lassen!\"  2. Mit so ''nem Sprung in der Schüssel würd ich mich an seiner Stelle resetten lassen!  3. Mit so ''nem Dauerdachschaden wie der würd ich mich freiwillig recyclen lassen!"}]'::jsonb, 'an Hianpecka haum'),
  ('an-dauapecka-haum', 'an Dauapecka haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Dauerpecker haben', '[{"kategorie": "wörtlich", "text": "\"einen bleibenden geistigen Schaden haben\""}, {"kategorie": "", "text": "\"eine Vollmeise haben\""}, {"kategorie": "", "text": "\"einen Dauerdachschaden haben\""}, {"kategorie": "", "text": "\"einen lebenslangen Sprung in der Schüssel haben\""}]'::jsonb, 'Dea hod kan Voogl, dea hod an Dauapecka!'),
  ('dea-hod-kan-voogl-dea-hod-an-dauapecka', 'Dea hod kan Voogl, dea hod an Dauapecka!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat keinen Vogel, der hat einen Dauerpecker', '[{"kategorie": "wörtlich", "text": "\"Der hat keinen Vogel, der hat einen lebenslangen Dauerdachschaden!\"  2. Der hat keine Meise, der hat ''nen Specht im Kopf, der ihm sukzessive das Hirn rauspickt!  3. Der hat keinen Sprung in der Schüssel – bei dem geht der Riss quer durchs gesamte Hirn!  4. Der hat keinen Vogel – bei dem hackt der Specht im 24/7-Schichtbetrieb!"}]'::jsonb, 'an Dauapecka haum'),
  ('do-rauchds-im-hiankaastl', 'Do rauchds im Hiankaastl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da raucht''s im Hirnkastl!', '[{"kategorie": "wörtlich", "text": "\"Da läuft das Hirnkästchen heiß!\"  2. \"Da brutzeln die Synapsen!\"  3. \"Da qualmt''s im Oberstübchen!\""}]'::jsonb, ''),
  ('dea-hod-nix-in-sein-hiankaastl', 'Dea hod nix in sein Hiankaastl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hat nichts in seinem Hirnkästchen', '[{"kategorie": "wörtlich", "text": "\"Der hat nichts im Oberstübchen!\"  2. \"Der ist komplett intelligenzbefreit!\"  3. \"Der ist dumm wie die Nacht!\""}]'::jsonb, ''),
  ('hods-hiankastl-bei-dia-heid-ned-aufgschbead', 'Hods Hiankastl bei dia heid ned aufgschbead?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hat das Hirnkastl bei dir heut nicht aufgesperrt?', '[{"kategorie": "wörtlich", "text": "\"Tut sich heut nichts bei dir im Oberstübchen?\"  2. \"Hat dein Hirn auf Durchzug geschaltet?\"  3. \"Brennt bei dir noch Licht im Oberstübchen?\"  4. \"Hast du einen Sprung in der Schüssel?\"  5. Bist [[gfäud]] in da Marüün?\""}]'::jsonb, ''),
  ('des-geed-ma-ned-in-mei-hiankaastl', 'Des geed ma ned in mei Hiankaastl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das geht mir nicht in mein Hirnkastl', '[{"kategorie": "wörtlich", "text": "\"Das geht mir einfach nicht ein!\"  2. \"Das will einfach nicht in meinen Kopf!\"  3. \"Das krieg ich einfach nicht gebacken!\""}]'::jsonb, ''),
  ('des-geed-ma-aafoch-ned-ei', 'Des geed ma aafoch ned ei!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das geht mir einfach nicht ein!', '[{"kategorie": "wörtlich", "text": "\"Das geht mir einfach nicht in mein Hirnkastl!\"  2. \"Das will einfach nicht in meinen Kopf!\"  3. \"Das krieg ich einfach nicht gebacken!\""}]'::jsonb, ''),
  ('des-hiankaastl-oisschoidn', 'des Hiankaastl oisschoidn', '', '', '', 'Wiener Sprüche, die sitzen!', 'das Hirnkastl ausschalten', '[{"kategorie": "wörtlich", "text": "\"das Gehirn ausschalten\""}, {"kategorie": "", "text": "\"das Gehirn auf Durchzug schalten\", \"das Gehirn auf Flugmodus stellen\", \"die Denkzentrale abschalten\""}, {"kategorie": "fig.", "text": "kopflos agieren, unüberlegt handeln, jegliche Vernunft außer Acht lassen, nicht viel nachdenken"}]'::jsonb, ''),
  ('waunnsd-mit-meina-oidn-dischkutiasd-muassd-vuahea-s-hiankaastl-ausschoidn', 'Waunnsd mit meina Oidn dischkutiasd, muassd vuahea s''Hiankaastl ausschoidn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du mit meiner Alten diskutierst, musst vorher du das Hirnkastl ausschalten!', '[{"kategorie": "wörtlich", "text": "\"Wenn du mit meiner Alten diskutierst, schaltest du besser gleich auf Standby!\"  2. Mit meiner Frau diskutieren? Da hilft nur Hirn aus – und Gesicht auf Durchzug!  3. Diskutieren mit meiner Frau geht nur, wenn man das eigene Hirn vorher ausschaltet!"}]'::jsonb, 'des Hiankaastl oisschoidn'),
  ('waunn-mei-oide-augfressn-is-schoids-des-hiankaastl-aus-und-lossd-nua-no-de-pappulatua-renna', 'Waunn mei Oide augfressn is, schoids des Hiankaastl aus und lossd nua no de Pappulatua renna!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn meine Alte angefressen ist, schaltet sie das Hirnkastl aus und lässt nur die Pappulatur rennen!', '[{"kategorie": "wörtlich", "text": "\"Wenn meine Frau sauer ist, schaltet sie sofort das Hirnkastl aus und lässt nur noch das Mundwerk laufen!\"  2. Wenn meine Alte wütend ist, stellt sie das Denken ein und lässt nur noch ihr Mundwerk laufen!  3. Wenn meine Frau sauer ist, macht das Hirnkastl dicht – und das Maul geht auf wie’n Presslufthammer!"}]'::jsonb, 'des Hiankaastl oisschoidn'),
  ('oame-ritta', 'oame Ritta', 'die', '', '', 'Wiener Küche & Gaumenfreuden', 'arme Ritter', '[{"kategorie": "wörtlich", "text": "\"arme Ritter\" (uralte Süßspeise, schon bei den alten Römern bekannt - abgeleitet von deren \"großem, rechteckigem Ritterschild\")"}, {"kategorie": "Kulinarik", "text": "Süßspeise aus zwei zusammengelegten, mit Marmeldade bestrichenen Weißbrotscheiben"}]'::jsonb, ''),
  ('bei-uns-in-wiin-soogd-ma-imma-no-pofeesn-und-ned-oame-ritta-des-is-nix-aundas-ois-oidbockans-brood-in-mueuech-und-ei-eitunkd-in-fett-ausboochn-und-mit-zucka-augschdraad', 'Bei uns in Wiin soogd ma imma no ''Pofeesn'', und ned ''oame Ritta'' - des is nix aundas ois oidbockans Brood, in Müüch und Ei eitunkd, in Fett ausboochn und mit Zucka augschdraad!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Bei uns in Wien sagen wir immer noch ''Pofesen'', und nicht ''arme Ritter'' - das ist nichts anderes als altbackenes Brot, in Milch und Ei eingetunkt, in Fett ausgebacken und mit Zucker angestreut!', '[{"kategorie": "wörtlich", "text": "\"Bei uns heißen die ‚armen Ritter‘ einfach Pofesen – altbackenes Brot in Milch und Ei getunkt, in Fett ausgebraten und mit Zucker bestreut!\"  2. Pofesen sind im Grunde das Gleiche wie arme Ritter - nur oft mit Marmelade gefüllt, in Fett ausgebacken und mit Zucker bestreut!  3. Meine Oma hat früher immer Pofesen gemacht – ich hab erst später erfahren, dass das in Deutschland ‚arme Ritter‘ heißt!"}]'::jsonb, 'oame Ritta'),
  ('hianpofeesn-wean-aus-zwa-zsaummgleegde-weissbroodscheibm-gmocht-mit-koibshian-gfueued-daunn-paniad-und-zum-schluss-in-fett-ausboochn', 'Hianpofeesn wean aus zwa zsaummgleegde Weissbroodscheibm gmocht, mit Koibshian gfüüd,  daunn paniad und zum Schluss in Fett ausboochn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Hirnpofesen werden aus zwei zusammengelegten Weißbrotscheiben gemacht, mit Kalbshirn gefüllt, dann paniert und zum Schluss in Fett ausgebacken!', '[{"kategorie": "wörtlich", "text": "\"Hirnpofesen werden aus zwei Weißbrotscheiben zubereitet, mit Kalbshirn gefüllt, dann paniert und schließlich in Fett ausgebacken!\"  2. Für Hirnpofesen werden zwei Weißbrotscheiben mit einer Kalbhirnmasse belegt, zusammengedrückt, in Ei und Brösel gewälzt und schließlich knusprig ausgebraten!  3. Hirnpofesen sind eine Wiener Delikatesse aus Brot, Kalbshirn und Bröseln – außen kross, innen weich, voll Aroma!"}]'::jsonb, ''),
  ('ins-pofeesnkammal-kummd-imma-koibshian-gwiazd-mit-peedasueue-soiz-und-pfeffa-und-vefaeinad-mit-an-schuss-oowas-oda-an-eigoeoeb-fiad-bindung-daunn-nua-no-ausboochn-und-featig-san-de-hianpofeesn', 'Ins Pofeesnkammal kummd imma Koibshian, gwiazd mit Peedasüü, Soiz und Pfeffa, und vefaeinad mit an Schuss Oowas oda an Eigööb fiad Bindung - daunn nua no ausboochn, und featig san de Hianpofeesn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ins Pofesenkammerl kommt immer Kalbshirn, gewürzt mit Petersilie, Salz und Pfeffer, und verfeinert mit einem Schuss Obers oder einem Eigelb für die Bindung - dann nur noch ausbacken, und fertig sind die Hirnpofesen!', '[{"kategorie": "wörtlich", "text": "\"In die Teigtasche kommt immer Kalbshirn, gewürzt mit etwas fein gehackter Petersilie, Salz und Pfeffer, und verfeinert mit einem Schuss Obers oder einem Eigelb für die Bindung - dann nur noch frittieren, und fertig sind die Hirnpofesen!\"  2. Die Füllung der Hirnpofesen besteht traditionell aus Kalbshirn, fein abgeschmeckt mit Petersilie, Salz und Pfeffer, ein Schuss Obers oder etwas Eigelb sorgt für die nötige Bindung – und zum Schluss werden die Pofesen in heißem Fett knusprig ausgebacken!  3. Das feine Kalbshirn wird aromatisch veredelt mit frischer Petersilie, etwas Salz und Pfeffer, sanft gebunden mit einem Hauch Obers oder Eigelb – eingebettet zwischen zwei Weißbrotscheiben, und schließlich im heißen Fett goldgelb zur Hirnpofese ausgebacken!"}]'::jsonb, ''),
  ('den-sei-hiankaastl-is-eeha-a-pofeesnkammal-gfueued-min-hian-von-an-koib', 'Den sei Hiankaastl is eeha a Pofeesnkammal - gfüüd min Hian von an Koib!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Dem sein Hirnkastl ist eher ein Pofesenkammerl - gefüllt mit dem Hirn eines Kalbs!', '[{"kategorie": "wörtlich", "text": "\"Sein Oberstübchen ist eher ein Pofesenkammerl - gefüllt mit Kalbshirn statt mit Menschenverstand!\"  2. Sein Oberstübchen ist weniger Denkzentrale, mehr Teigtasche – gefüllt mit weichgekochtem Kalbshirn!  3. Da oben in seinem Hirn sitzt keine Intelligenz – das ist eher ein Brotbehälter mit Kalbshirnfüllung!"}]'::jsonb, ''),
  ('foeoed-da-wos-im-oowaschdiiwal', 'Fööd da wos im Oowaschdiiwal?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Fehlt dir was im Oberstüberl?', '[{"kategorie": "wörtlich", "text": "\"Fehlt dir was im Oberstübchen?\"  2. \"Brennt bei dir noch Licht im Oberstübchen?\"  3. \"Hast du einen Sprung in der Schüssel?\"  4. \"Bist du im Oberstübchen falsch verdrahtet?\"  5. \"Bist [[gfäud]] in da Marüün?\""}]'::jsonb, ''),
  ('dea-is-ned-gaunz-dicht-im-oowaschdiiwal', 'Dea is ned gaunz dicht im Oowaschdiiwal!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der ist nicht ganz dicht im Oberstüberl!', '[{"kategorie": "wörtlich", "text": "\"Der ist nicht ganz dicht im Oberstübchen!\"  2. \"Der hat einen [[Sprung]] in der Schüssel!  3. Der hat nicht alle Tassen im Schrank!  4. Dea is [[gfäud]] in da Marüün!  5. [[Dea muass im Oowaschdiiwal foisch vadrooded sei!]]"}]'::jsonb, ''),
  ('dea-muass-im-oowaschdiiwal-foisch-vadrooded-sei', 'Dea muass im Oowaschdiiwal foisch vadrooded sei!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der muss im Oberstüberl falsch verdrahtet sein!', '[{"kategorie": "wörtlich", "text": "\"Der muss im Oberstübchen falsch verdrahtet sein!\"  2. \"Der ist nicht ganz dicht im Oberstübchen!\"  3. \"Der muss einen [[Sprung]] in der Schüssel haben!\"  4. \"Dea muass [[hiinnich]] in da Marüün sei!\""}]'::jsonb, 'Dea is ned gaunz dicht im Oowaschdiiwal!'),
  ('dea-hod-a-schbotznhian-glaubd-owa-ea-is-da-einschdein', 'Dea hod a Schbotznhian, glaubd owa, ea is da Einschdein!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat ein Spatzenhirn, glaubt aber, er ist der Einstein!', '[{"kategorie": "wörtlich", "text": "\"Der hat null in der Birne, glaubt aber, er ist Professor Einstein!\"  2. Dumm wie Bohnenstroh, aber eingebildet wie Oskar!  3. Der hat ein Gehirn in der Größe eines Gummibärlis - aber er selbst hält sich für die Wiedergeburt von Einstein!"}]'::jsonb, ''),
  ('des-schbotznhian-auf-zwa-fiass-wueue-ma-schdaendig-eaklaean-wiad-woeoed-funktioniad', 'Des Schbotznhian auf zwa Fiass wüü ma schdändig eakläan, wiad Wööd funktioniad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Spatzenhirn auf zwei Füßen will mir ständig erklären, wie die Welt funktioniert!', '[{"kategorie": "wörtlich", "text": "\"Das Spatzenhirn auf zwei Beinen will mir ständig erklären, wie die Welt funktioniert!\"  2. Der Typ mit seinem Ameisenhirn hat gerade genug Grips, um sich die Schuhe zuzubinden – aber hält mir Vorträge über das Universum!  3. Dieses Spatzenhirn auf Stelzen denkt, er wär Einstein und kann mir die Welt erklären!"}]'::jsonb, ''),
  ('lufthian-deppads-waassd-wos-du-bist-a-vakuumplutza-mit-sproochfunktion', 'Lufthian, deppads! Waassd wos du bist? A Vakuumplutza mit Sproochfunktion!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Lufthirn, deppertes! Weißt, was du bist? Ein Vakuumplutzer mit Sprachfunktion!', '[{"kategorie": "wörtlich", "text": "\"Lufthirn, deppertes! Weißt, was du bist? Ein Vakuumkopf mit Sprachfunktion!\"  2. \"Du blöde Hohlbirne! Weißt du, was du bist? Ein sprechender Staubsaugerbeutel mit Lautsprecher!\"  3. [[Du gschissana Hianhappla, du host a Hian wiara Luftballoon!]]"}]'::jsonb, ''),
  ('du-gschdoeada-hianhappla', 'Du gschdöada Hianhappla!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du gestörter Hirnhappler!', '[{"kategorie": "wörtlich", "text": "\"Du gestörte Hohlbirne!\"  2. \"Du blöder Vollidiot!\"  3. Du geistiger Totalschaden!\"  4. [[Du foisch vadrooteda Hianschissla!]]"}]'::jsonb, 'Du foisch vadrooteda Hianschissla!'),
  ('du-gschissana-hianhappla-du-host-a-hian-wiara-luftballoon', 'Du gschissana Hianhappla, du host a Hian wiara Luftballoon!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du geschissener Hirnhappler, du hast ein Hirn wie ein Luftballon!', '[{"kategorie": "wörtlich", "text": "\"Du verdammte Hohlbirne, du hast ein Hirn wie ein Luftballon!\"  2. Du gottverdammter Hohlkopf – du hast ein Lufthirn im Leerlauf!  3. Du verfluchter Vakuumkopf - dir müssen sie wohl schon die letzte Restluft ausm Gehirn abgesaugt haben!"}]'::jsonb, 'Lufthian, deppads! Waassd wos du bist? A Vakuumplutza mit Sproochfunktion!'),
  ('du-foisch-vadrooteda-hianschissla', 'Du foisch vadrooteda Hianschissla!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du falsch verdrahteter Hirnschüssler!', '[{"kategorie": "wörtlich", "text": "\"Du falsch verdrahtete Hohlbirne!\"  2. \"Du geistiger Totalschaden!\"  3. [[Du gschdöada Hianhappla!]]"}]'::jsonb, 'Du gschdöada Hianhappla!'),
  ('waunnsd-des-hiangruellal-wos-froogsd-kummd-nua-a-leises-ziapn-zruck', 'Waunnsd des Hiangrüllal wos froogsd, kummd nua a leises Ziapn zruck!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn du dieses Hirngrillerl was fragst, kommt nur ein leises Zirpen zurück!', '[{"kategorie": "wörtlich", "text": "\"Wenn du dieses Hirngrillchen was fragst, kommt nur ein leises Zirpen zurück!\"  2. Im Hirnkastl von diesem Schwachkopf wohnt genau eine Grille – und selbst die zirpt nur fallweise!  3. Fragst du das Grillenhirn was, kommt nichts zurück - außer ein leises Zirpen der Dummheit!"}]'::jsonb, ''),
  ('dia-haums-ins-hian-gschissn-und-ned-owelossn', 'Dia haums ins Hian gschissn und ned owelossn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Dir haben sie ins Hirn geschissen und nicht runtergelassen!', '[{"kategorie": "wörtlich", "text": "\"Dir haben sie ins Hirn geschissen und vergessen, die Klospülung zu betätigen!\"  2. Dir haben sie ins Hirn geschissen, den Deckel offengelassen und nicht gespült!  3. In deinem Schädel is mehr Luft als Hirn – und das bisschen hat Verstopfung!  4. Dein Hirn ist wie ein Bahnhofsklo – zugeschissen, verstopft und ohne Spülung!"}]'::jsonb, ''),
  ('des-bauxal-hod-am-daam-gluudld-bis-eigschloofn-is', 'Des Bauxal hod am Daam gluudld, bis eigschloofn is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Bauxerl hat am Daumen geludelt, bis es eingeschlafen ist!', '[{"kategorie": "wörtlich", "text": "\"Das Kindlein nuckelte am Daumen, bis es eingeschlafen war!\"  2. Das Baby lutschte am Daumen, bis es selig eingeschlummert ist!  3. Der kleine Knirps saugte am Daumen, bis er ins Träumeland wegnickte!"}]'::jsonb, ''),
  ('si-hods-buuwal-a-schdund-laung-in-schloof-gluudld', 'Si hods Buuwal a Schdund laung in Schloof gluudld!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie hat das Buberl eine Stunde lang in den Schlaf geludelt!', '[{"kategorie": "wörtlich", "text": "\"Sie hat das Bübchen eine Stunde lang in den Schlaf gelullt!\"  2. Sie hat den kleinen Jungen eine Stunde lang in den Schlaf gesungen!  3. Sie hat den Kleinen eine Stunde lang eingelullt, bis er schließlich weggenickt ist!"}]'::jsonb, ''),
  ('beim-luudln-nua-ned-huudln', 'Beim Luudln nua ned huudln!', '', '', '', 'Echte Wiener Schmähperlen', 'Beim Ludeln nur nicht hudeln!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Beim Wasserlassen schön gelassen!\"  2. \"Zeit lassen beim Wasserlassen!\"  3. \"Lass den Bierstrahl langsam fließen!\"  4. Beim [[Brunzen]] nichts verhunzen!"}]'::jsonb, ''),
  ('beim-brunzn-nix-vahunzn', 'Beim Brunzn nix vahunzn!', '', '', '', 'Echte Wiener Schmähperlen', 'Beim Brunzen nichts verhunzen!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Beim Wasserlassen schön gelassen!\"  2. \"Zeit lassen beim Wasserlassen!\"  3. \"Lass den Bierstrahl langsam fließen!\"  4. Beim [[Ludeln]] nur nicht hudeln!"}]'::jsonb, ''),
  ('dea-luudld-aun-seina-zigaan-wiara-bejby-aun-da-muttabrust', 'Dea luudld aun seina Zigaan wiara Bejby aun da Muttabrust!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der ludelt an seiner Zigarre wie ein Baby an der Mutterbrust!', '[{"kategorie": "wörtlich", "text": "\"Der nuckelt an seiner Zigarre wie ein Baby an der Mutterbrust!\"  2. Der saugt an seiner Zigarre wie ein Säugling an der Milchzapfstelle!  3. Er kaut und saugt an seiner Zigarre mit der Inbrunst eines Babys, das an der Mutterbrust nuckelt!"}]'::jsonb, ''),
  ('wiar-i-s-bauxal-hochheeb-und-fias-foto-in-oam-nimm-hods-mi-von-oobm-bis-unt-auduudld', 'Wiar I s''Bauxal hochheeb und fias Foto in Oam nimm, hods mi von oobm bis unt auduudld!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie ich das Bauxerl hochheb'' und fürs Foto in den Arm nehm'', hat''s mich von oben bis unten angedudelt!', '[{"kategorie": "wörtlich", "text": "\"Ich heb das Kleine hoch, grinse für''s Foto – und zack, es pieselt mich komplett an!\"  2. Als ich das Baby für''s Foto in die Arme nahm, hat es mich von oben bis unten angepinkelt!  3. Ich hielt den süßen Knirps für''s Foto hoch – und wurde zum Dank von oben bis unten angebrunzt!"}]'::jsonb, ''),
  ('si-auluudln', 'si auluudln', '', '', '', 'Grundwortschatz Wienerisch', 'sich anludeln', '[{"kategorie": "wörtlich", "text": "\"sich anludeln\" (vom mittelhochdeutschen \"lūdelen\"=\"lullen\")"}, {"kategorie": "allg.", "text": "sich anpinkeln, sich anpieseln, in die Hose machen, [[sich]] anbrunzen, [[sich]] anseichen"}]'::jsonb, 'Waunn da Schorschi noch siebm Gschbritzde aufs Heisl geed, kaunnsd da sicha sei, dass a si von oobm bis unt auluudld!'),
  ('waunn-da-schorschi-noch-siebm-gschbritzde-aufs-heisl-geed-kaunnsd-da-sicha-sei-dass-a-si-von-oobm-bis-unt-auluudld', 'Waunn da Schorschi noch siebm Gschbritzde aufs Heisl geed, kaunnsd da sicha sei, dass a si von oobm bis unt auluudld!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn der Schorschi nach sieben Gespritzten aufs Häusl geht, kannst du dir sicher sein, dass er sich von oben bis unten anludelt!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Schorschi nach sieben Spritzweinen aufs Klo geht, kannst du dir sicher sein, dass er sich von oben bis unten anpieselt!\"  2. Wenn der Schorschi sieben Spritzer intus hat, kannst du wetten, dass er sich am Klo von oben bis unten anbrunzt!  3. Mit sieben Spritzweinen im Blut ist Schorschi auf dem Klo sein schlimmster Feind – da pinkelt er sich nämlich immer von oben bis unten selbst an!"}]'::jsonb, 'si auluudln'),
  ('maunche-nuckln-aum-weiglaasl-ois-daedns-aun-an-luudl-saung', 'Maunche nuckln aum Weiglaasl, ois dädns aun an Luudl saung!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Manche nuckeln am Weinglas, als täten sie an einem Ludel saugen!', '[{"kategorie": "wörtlich", "text": "\"Manche nuckeln am Weinglas, als würden sie an einem Luller saugen!\"  2. Manche hängen am Weinglas wie ein Baby am Schnuller!  3. Manche führen das Weinglas zum Mund wie einen heiligen Gral – und saugen dann daran wie Säuglinge an einem Schnuller!"}]'::jsonb, ''),
  ('a-stejk-ghead-uandlich-mid-oeoe-eipinsld-bevua-mas-aum-grueue-haud', 'A Stejk ghead uandlich mid Öö eipinsld, bevua mas aum Grüü haud!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Steak gehört ordentlich mit Öl eingepinselt, bevor man es auf den Grill haut!', '[{"kategorie": "wörtlich", "text": "\"Ein Steak muss vorher ordentlich eingeölt werden, bevor es auf den Grill kommt!\"  2. Bevor das Steak auf den Rost fliegt, sollte man es kräftig mit Öl einpinseln!  3. Ein gutes Steak sollte man vor dem Grillen mit Öl bestreichen – erstens schmeckt''s dann besser, und zweitens klebt''s nicht am Rost fest!"}]'::jsonb, ''),
  ('fia-maunche-is-oeoe-des-schwoaze-goid-fia-aundare-nua-de-dreckschmiian-de-unsan-planeetn-roniad', 'Fia maunche is Öö des schwoaze Goid - fia aundare nua de Dreckschmiian, de unsan Planeetn roniad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Für manche ist Öl das schwarze Gold - für andere nur die Dreckschmiere, die unseren Planeten ruiniert!', '[{"kategorie": "wörtlich", "text": "\"Für die einen ist Erdöl das schwarze Gold – für die anderen das schwarze Gift, das unsere Zukunft vergiftet!\"  2. Manche sehen im Öl das schwarze Gold – andere sehen darin den schleichenden Tod unseres Planeten!  3. Für die einen ist Öl Reichtum – für die anderen der flüssige Abgrund, in den wir die Erde stoßen!"}]'::jsonb, ''),
  ('im-oeoe-sei', 'im Öö sei', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'im Öl sein', '[{"kategorie": "scherzhaft für", "text": "\"einen Vollrausch haben\""}, {"kategorie": "", "text": "[[blunzenfett]] sein"}, {"kategorie": "", "text": "[[in der Vollglut sein]]"}, {"kategorie": "", "text": "\"in der Fetten sein\""}]'::jsonb, 'Nooch fünf Bia bin I no laung ned im Öö!'),
  ('nooch-fuenf-bia-bin-i-no-laung-ned-im-oeoe', 'Nooch fünf Bia bin I no laung ned im Öö!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Nach fünf Bier bin ich noch lang nicht im Öl!', '[{"kategorie": "wörtlich", "text": "\"Nach fünf Bier bin ich längst noch nicht betrunken!\"  2. Nach fünf Bier hab ich noch lange keinen Rausch - da kann ich noch rückwärts tanzen und geradeaus reden!  3. Bei fünf Bier war ich noch nie im Öl - das ist mein Grundpegel!"}]'::jsonb, 'im Öö sei'),
  ('kaum-gibds-freibia-schdeed-de-gaunze-packlrass-aa-scho-auf-da-mattn', 'Kaum gibds Freibia, schdeed de gaunze Packlrass aa scho auf da Mattn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Kaum gibt''s Freibier, steht die ganze Packelrass'' auch schon auf der Matte!', '[{"kategorie": "wörtlich", "text": "\"Kaum gibt''s Freibier, steht die ganze Halunkenbande auch schon auf der Matte!\"  2. Sobald der Freibier-Alarm ertönt, ist die ganze Mischpoche auch schon vor dem Zapfhahn versammelt!  3. Kaum gibt’s Freibier, kommt auch schon die ganze Schnorrerbande angerückt!"}]'::jsonb, ''),
  ('packlrass-iwaranaund', 'Packlrass iwaranaund!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Packlrass übereinand!', '[{"kategorie": "wörtlich, Beschimpfung", "text": "\"Ihr schäbiges Pack hoch zehn!\"  2. \"Ihr elendes Gesindel zum Quadrat!\"  3. \"Ihr Bande verkommener Gestalten!\"  4. [[Bagaasch iwaranaund!]]"}]'::jsonb, 'Bagaasch iwaranaund!'),
  ('bagaasch-iwaranaund', 'Bagaasch iwaranaund!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Bagage übereinand!', '[{"kategorie": "wörtlich, Beschimpfung", "text": "\"Ihr schäbiges Pack hoch zehn!\"  2. \"Ihr elendes Gesindel zum Quadrat!\"  3. \"Ihr Bande verkommener Gestalten!\"  4. [[Packlrass iwaranaund!]]"}]'::jsonb, 'Packlrass iwaranaund!'),
  ('du-damischa-kosak-russischa-iwaranaund', 'Du damischa Kosak, russischa, iwaranaund!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du damischer Kosak, russischer, übereinand!', '[{"kategorie": "wörtlich, Beschimpfung", "text": "\"Du dämlicher Kosake, russischer, zum Quadrat!\"  2. (Gaunerjargon): \"Du hinterfotziger, russischer Gauner hoch zehn!\"  3. \"Du hundsgemeiner, russischer Halunke zum Quadrat!\""}]'::jsonb, ''),
  ('kaum-gibds-wos-zum-earbm-schdeed-de-gaunze-mischpoch-auf-da-mattn', 'Kaum gibds wos zum Earbm, schdeed de gaunze Mischpoch auf da Mattn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Kaum gibt’s was zu erben, steht die ganze Mischpoche auf der Matte!', '[{"kategorie": "wörtlich", "text": "\"Kaum gibt’s was zu erben, steht die ganze Sippschaft auch schon auf der Matte!\"  2. Sobald es was zu erben gibt, kommt die ganze leidliche Blutsbande aus allen Löchern gekrochen!  3. Wenn ein Erbe winkt, steht die ganze Packelrass plötzlich wieder versammelt vor der Tür!"}]'::jsonb, ''),
  ('mit-so-aana-mischpoch-wueuel-i-nix-z-tuan-haum', 'Mit so aana Mischpoch wüül I nix z''tuan haum!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit so einer Mischpoche will ich nichts zu tun haben!', '[{"kategorie": "wörtlich", "text": "\"Mit so einer Clique will ich nichts zu tun haben!\"  2. Mit so einem Gesindel will ich mich gar nicht erst abgeben!  3. So ein liederliches Pack kommt mir nicht ins Haus!"}]'::jsonb, ''),
  ('da-pappnschlossa-hod-meine-zeend-saniad-jetzd-hob-i-zwaa-lecha-mea-aans-in-da-goschn-und-aans-in-mein-goeoedbeidl', 'Da Pappnschlossa hod meine Zeend saniad - jetzd hob I zwaa Lecha mea: aans in da Goschn und aans in mein Göödbeidl!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Der Pappenschlosser hat meine Zähne saniert – jetzt hab ich zwei Löcher mehr: eines in der Goschen und eines in meinem Geldbeutel!', '[{"kategorie": "wörtlich", "text": "\"Der Maulklempner hat meine Zähne saniert – jetzt hab ich zwei Löcher mehr: eines im Maul und eines in meinem Geldbeutel!\"  2. Der Zahnarzt hat meine Kauleiste saniert – jetzt hab ich zwei neue Löcher: eins im Maul, eins im Geldbörserl!  3. Der Pappenschlosser hat mir ein Loch im Zahn gestopft und zwei andere aufgerissen – eins im Maul und eins im Portemonnaie!"}]'::jsonb, ''),
  ('da-pappnschbengla-hod-ma-de-zeend-saniad-jetzd-hob-i-a-gebiss-wiara-holliwud-star-und-an-kontoschdaund-wiara-obdochloosa', 'Da Pappnschbengla hod ma de Zeend saniad - jetzd hob I a Gebiss wiara Holliwud-Star und an Kontoschdaund wiara Obdochloosa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Pappenspengler hat mir die Zähne saniert - jetzt hab ich ein Gebiss wie ein Hollywood-Star und einen Kontostand wie ein Obdachloser!', '[{"kategorie": "wörtlich", "text": "\"Der Maulklempner hat mir die Zähne saniert - jetzt hab ich ein Gebiss wie ein Hollywood-Star und einen Kontostand wie ein Obdachloser!\"  2. Der Zahndoc hat mir die Beißer rausgeputzt – jetzt hab ich ein Filmstar-Grinsen und einen Kontostand zum Weinen!  3. Der Zahnarzt hat mein Gebiss aufpoliert – jetzt hab ich ein Million-Dollar-Lächeln und null auf dem Konto!"}]'::jsonb, ''),
  ('goschnschuasta-is-da-aanzige-beruf-woosd-dafia-zoid-wiasd-dassd-aundare-quoeoesd', 'Goschnschuasta is da aanzige Beruf, woosd dafia zoid wiasd, dassd aundare quöösd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Goschenschuster ist der einzige Beruf, wo man dafür bezahlt wird, dass man andere quält!', '[{"kategorie": "wörtlich", "text": "\"Zahnarzt ist der einzige Beruf, bei dem man dafür bezahlt wird, dass man andere quält!\"  2. Zahnarzt: Der Traumjob für alle, die andere leiden sehen wollen und sich dafür auch noch bereichern!  3. Beim Goschenschuster bezahlst du jemanden dafür, dir wehzutun. Das ist wie ''ne bezahlte Stunde im Sado-Maso-Studio!"}]'::jsonb, ''),
  ('des-gschaefdsmodoeoe-von-mein-goschnschbengla-ea-buad-ma-lecha-ind-zeend-und-no-greessare-in-mein-goeoedbeidl', 'Des Gschäfdsmodöö von mein Goschnschbengla: Ea buad ma Lecha ind Zeend und no greessare in mein Göödbeidl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Das Geschärftsmodell von meinem Goschenspengler: Er bohrt mir Löcher in die Zähne und noch größere in meinen Geldbeutel!', '[{"kategorie": "wörtlich", "text": "\"Das Business-Modell meines Zahnarztes: Er bohrt mir Löcher in Zähne und noch größere in meinen Geldbeutel!\"  2. Das Geschäftsmodell meines Zahnarztes: Löcher füllen im Mund, dafür welche reißen im Portemonnaie!  3. Die Methode von meinem Zahndoc: Mit dem Bohrer meine Zähne reparieren und mit der Rechnung meinen Kontostand ruinieren!"}]'::jsonb, ''),
  ('si-iwa-wem-de-pappn-zreissn', 'si iwa wem de Pappn zreissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich über jemanden die Pappen zerreißen', '[{"kategorie": "wörtlich", "text": "\"sich das Maul über jemanden zerreißen\""}, {"kategorie": "", "text": "sich die [[Goschen]] über jemanden zerreißen"}, {"kategorie": "", "text": "gegen jemanden vom Leder ziehen"}, {"kategorie": "", "text": "über jemanden übel herziehen"}, {"kategorie": "", "text": "[[sich]] das Maul ausleeren"}, {"kategorie": "", "text": "[[sich]] das Maul wetzen"}]'::jsonb, 'Aun da Schaunk zreissn sa si unentweegd de Pappn iwan Schääf - owa eam ins Gsichd soogds kaana!'),
  ('aun-da-schaunk-zreissn-sa-si-unentweegd-de-pappn-iwan-schaeaef-owa-eam-ins-gsichd-soogds-kaana', 'Aun da Schaunk zreissn sa si unentweegd de Pappn iwan Schääf - owa eam ins Gsichd soogds kaana!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'An der Schank zerreißen sie sich unentwegt die Pappen über den Chef - aber ihm ins Gesicht sagt''s keiner!', '[{"kategorie": "wörtlich", "text": "\"An der Theke zerreißen sie sich pausenlos das Maul über den Chef - aber ihm ins Gesicht sagt''s keiner!\"  2. An der Schank leeren sie sich alle das Maul über den Chef aus - aber wenn er auftaucht, sind die Maulhelden plötzlich ruhig!  3. An der Theke wird so lange gegen den Chef vom Leder gezogen, bis er den Raum betritt – dann fallen alle tot um!"}]'::jsonb, 'si iwa wem de Pappn zreissn'),
  ('waunn-i-voifett-zu-meina-oidn-haamkuum-schlogd-mei-innares-pendl-nua-noo-zwischn-hoffnung-und-aungsd-aus', 'Waunn I voifett zu meina Oidn haamkuum, schlogd mei innares Pendl nua noo zwischn Hoffnung und Aungsd aus!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn ich vollfett zu meiner Alten heimkomme, schlägt mein inneres Pendel nur noch zwischen Hoffnung und Angst aus!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich voll wie ein Fass zu meiner Frau nach Hause komme, pendel ich innerlich nur noch zwischen Angst und Hoffnung!\"  2. Wenn ich vollbesoffen heimtorkle, tanzt mein inneres Pendel im Takt von Angst, Hoffnung und schlechten Ausreden!  3. Angetrunken auf Heimkehr – mein inneres Pendel schwingt nur noch zwischen Liebeshoffnung und Höllenfeuer!"}]'::jsonb, ''),
  ('si-ins-pendl-haun', 'si ins Pendl haun', '', '', '', 'Tod und Sterben auf Wienerisch', 'sich ins Pendel hauen', '[{"kategorie": "wörtlich", "text": "\"sich ins Pendel schmeißen\" (Metapher: Wenn sich ein Mensch erhängt, schwingt der Körper oft leicht hin und her, besonders zu Beginn. Diese schaukelnde Bewegung erinnert an ein Pendel [zum Beispiel von einer Standuhr]. Das Bild vergleicht also den erhängten Körper mit einem schwingenden Pendel)"}, {"kategorie": "Gaunersprache", "text": "sich erhängen, sich das Leben nehmen, Selbstmord begehen (durch Erhängen), \"sich die letzte Krawatte umbinden\", [[si dahängan]], [[si ins Hangal schmeissn]], [[die Seilbahn in den Himmel nehmen]]"}]'::jsonb, 'Da Waldi hod si weeng dea Huanfut ins Pendl ghaud - I kaunns imma no ned glaubm!'),
  ('da-waldi-hod-si-weeng-dea-huanfut-ins-pendl-ghaud-i-kaunns-imma-no-ned-glaubm', 'Da Waldi hod si weeng dea Huanfut ins Pendl ghaud - I kaunns imma no ned glaubm!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Waldi hat sich wegen dieser Hurenfut ins Pendel gehauen - ich kann''s immer noch nicht glauben!', '[{"kategorie": "wörtlich", "text": "\"Der Waldemar hat sich wegen dieser Hurenvotze erhängt - ich kann''s immer noch nicht fassen!\"  2. Wegen dieser ‚Dame‘ hat sich Waldemar das Leben genommen – unfassbar, einfach unglaublich!  3. Der Waldemar hat sich wegen dieser treulosen Person umgebracht – ich fass’ es einfach nicht!"}]'::jsonb, 'si ins Pendl haun'),
  ('wem-de-bleikrawattn-umbindn', 'wem de Bleikrawattn umbindn', '', '', '', 'Wiener Gaunersprache', 'jemandem die Bleikrawatte umbinden', '[{"kategorie": "wörtlich", "text": "\"jemandem den Bleischal umhängen\""}, {"kategorie": "", "text": "\"jemanden Blei schlucken lassen\""}, {"kategorie": "", "text": "\"jemandem den Bleisegen erteilen\""}, {"kategorie": "", "text": "\"jemanden Blei fressen lassen\""}]'::jsonb, 'A Wuat zua Hää - und I bind da de Bleikrawattn um!'),
  ('a-wuat-zua-haeae-und-i-bind-da-de-bleikrawattn-um', 'A Wuat zua Hää - und I bind da de Bleikrawattn um!', '', '', '', 'Wiener Gaunersprache', 'Ein Wort zur Höh - und ich bind dir die Bleikrawatte um!', '[{"kategorie": "wörtlich", "text": "\"Ein Wort zur Polizei - und ich lass dich Blei schlucken!\"  2. Ein Wort an die Bullen – und du kriegst den Bleisegen!  3. Verpfeifst du uns bei der Polizei, frisst du Blei!"}]'::jsonb, 'wem de Bleikrawattn umbindn'),
  ('wem-ins-pendl-haun', 'wem ins Pendl haun', '', '', '', 'Wiener Gaunersprache', 'jemanden ins Pendel hauen', '[{"kategorie": "wörtlich", "text": "\"jemanden ins Pendel schmeißen\" (Metapher: Wenn ein Mensch durch Erhängen stirbt, schwingt der Körper oft leicht hin und her, besonders zu Beginn. Diese schaukelnde Bewegung erinnert an ein Pendel [zum Beispiel von einer Standuhr]. Das Bild vergleicht also den erhängten Körper mit einem schwingenden Pendel)"}, {"kategorie": "Gaunersprache", "text": "jemanden erhängen, \"jemandem die letzte Krawatte umbinden\", \"jemanden die Seilbahn in den Himmel nehmen lassen\""}]'::jsonb, ''),
  ('ruck-ausse-mit-da-marii-oda-i-bind-da-dei-letzde-krawattn-um-und-hau-di-ins-pendl', 'Ruck ausse mit da Marii - oda I bind da dei letzde Krawattn um und hau di ins Pendl!', '', '', '', 'Wiener Gaunersprache', 'Rück raus die Marie - oder ich binde dir deine letzte Krawatte um und hau dich ins Pendl!', '[{"kategorie": "wörtlich", "text": "\"Rück raus die Kohle - oder ich binde dir die letzte Krawatte um den Hals  und schmeiß dich in den Strick!\"  2. Rück die Kohle raus – oder ich zieh dir deine letzte Krawatte um den Hals und schick dich über’n Jordan!  3. Her mit dem Zaster, sonst kriegst ''nen Strick um den Hals und trittst deine letzte Reise an!"}]'::jsonb, ''),
  ('de-saeubaun-in-himmae-neema', 'de Säubaun in Himmä neema', '', '', '', 'Tod und Sterben auf Wienerisch', 'die Seilbahn in den Himmel nehmen', '[{"kategorie": "wörtlich", "text": "\"sich mit einem Strick erhängen, um (vermeintlich) in den Himmel zu gelangen\""}, {"kategorie": "", "text": "\"sich das Leben nehmen\""}, {"kategorie": "", "text": "Selbstmord begehen (durch Erhängen)"}, {"kategorie": "", "text": "\"in die obere Etage abreiten\""}, {"kategorie": "", "text": "\"den Abgang nach oben wählen\""}, {"kategorie": "", "text": "[[si ins Pendl haun]]"}]'::jsonb, ''),
  ('da-vinz-hod-de-saeubaun-in-himmae-gnumma-zrucklossn-hoda-nuar-an-umghaudn-schaamae-und-an-haufn-schuidn', 'Da Vinz hod de Säubaun in Himmä gnumma - zrucklossn hoda nuar an umghaudn Schaamä und an Haufn Schuidn!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Vinz hat die Seilbahn in den Himmel genommen - zurückgelassen hat er nur einen umgeworfenen Schemel und einen Haufen Schulden!', '[{"kategorie": "wörtlich", "text": "\"Der Vinz hat seinem Leben ein Ende gesetzt – übrig blieb nur ein umgekippter Schemel und ein Berg unbezahlter Rechnungen!\"  2. Der Vinz ist abgeritten in die obere Etage – und hinterlassen hat er nichts außer ’nem umgestoßenen Hocker und seinen ganzen Schuldenkram!  3. Vinz hat den Abgang nach oben gewählt – zurückgelassen hat er nur ''nen umgeworfenen Schemel und ’ne ganze Wagenladung Schulden!"}]'::jsonb, 'de Säubaun in Himmä neema'),
  ('ooware-etaasch', 'ooware Etaasch', 'die', '', '', 'Grundwortschatz Wienerisch', 'obere Etage', '[{"kategorie": "wörtlich", "text": "\"Obergeschoß\" (vom französischen \"étage\"=\"Geschoß\")"}, {"kategorie": "allg.", "text": "\"Obergeschoß\", \"oberes Stockwerk\", \"Hochparterre\""}, {"kategorie": "fig., scherzhaft für", "text": "\"Himmelsstockwerk\", \"Himmelsparadies\", \"das himmlische Reich\""}]'::jsonb, 'In de oowaren Etaaschn von de Grindazeitheisa haum imma scho de bessagschdöödn Leit gwoond!'),
  ('in-de-oowaren-etaaschn-von-de-grindazeitheisa-haum-imma-scho-de-bessagschdoeoedn-leit-gwoond', 'In de oowaren Etaaschn von de Grindazeitheisa haum imma scho de bessagschdöödn Leit gwoond!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'In den oberen Etagen der Gründerzeithäuser haben immer schon die bessergestellten Leute gewohnt!', '[{"kategorie": "wörtlich", "text": "\"Schon immer lebten in den höheren Etagen der Gründerzeitbauten jene, die es sich leisten konnten!\"  2. Seit jeher waren die oberen Etagen in den Zinshäusern der Ringstraßenzeit den feinen Herrschaften vorbehalten!  3. Wer Rang und Vermögen hatte, residierte über dem Getriebe – in den oberen Etagen, die Licht, Ruhe und Aussicht versprachen!"}]'::jsonb, ''),
  ('ind-ooware-etaasch-ooreidn', 'ind ooware Etaasch ooreidn', '', '', '', 'Tod und Sterben auf Wienerisch', 'in die obere Etage abreiten', '[{"kategorie": "wörtlich", "text": "\"den Weg ins Jenseits antreten\""}, {"kategorie": "", "text": "\"in die ewigen Jagdgründe reiten\""}, {"kategorie": "", "text": "\"den letzten Ritt antreten\""}, {"kategorie": "", "text": "\"sterben\" (das Zeitliche segnen)"}, {"kategorie": "", "text": "[[de Bootschn aufschdöön]]"}]'::jsonb, 'Bevua I ind ooware Etaasch ooreid, sauf I in Heagood no in Messwei weg!'),
  ('bevua-i-ind-ooware-etaasch-ooreid-sauf-i-in-heagood-no-in-messwei-weg', 'Bevua I ind ooware Etaasch ooreid, sauf I in Heagood no in Messwei weg!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Bevor ich in die obere Etage abreite, sauf ich dem Herrgott noch seinen Messwein weg!', '[{"kategorie": "wörtlich", "text": "\"Bevor ich ins Himmelsstockwerk abreite, sauf ich dem Herrgott noch seinen Messwein weg!\"  2. Bevor ich himmelwärts ins Paradies reite, gurgel ich noch ein paar Tage den Messwein vom Pfarrer aus’m Tabernakel!  3. Bevor ich in die obere Etage abreite, sauf ich dem Herrgott noch die Ministrantenmilch weg!"}]'::jsonb, 'ind ooware Etaasch ooreidn'),
  ('du-vafickde-huanfut', 'Du vafickde Huanfut!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du verfickte Hurenfut!', '[{"kategorie": "wörtlich", "text": "\"Du durchgefickte Hurenvotze!\"  2. \"Du plattgevögeltes Hurenluder!\"  3. [[Du zuapuudade Huanschlaumpn!]]"}]'::jsonb, ''),
  ('wia-kaunn-ma-nua-auf-so-an-huantraumpae-einefoin', 'Wia kaunn ma nua auf so an Huantraumpä einefoin?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie kann man nur auf so einen Hurentrampel reinfallen?', '[{"kategorie": "wörtlich", "text": "\"Wie kann man nur auf so ein Hurenluder hereinfallen?\"  2. Wie kann man nur so blind sein und auf eine solche Hurenschlampe hereinfallen?  3. Wie kann man nur auf eine solche [[Hurenfut]] hereinfallen - manche Männer lernen’s einfach nie, oder?"}]'::jsonb, ''),
  ('weeng-dem-huanluada-hoda-ois-valuan-frau-kinda-und-sein-vaschdaund', 'Weeng dem Huanluada hoda ois valuan - Frau, Kinda und sein Vaschdaund!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wegen diesem Hurenluder hat er alles verloren – Frau, Kinder und seinen Verstand!', '[{"kategorie": "wörtlich", "text": "\"Wegen diesem Hurenluder hat er alles verloren – Frau, Kinder und den Verstand!\"  2. Dieser Hurentrampel war sein Untergang – durch sie verlor er seine Familie und schließlich den letzten Rest seiner Vernunft!  3. Wegen dieser [[Hurenfut]] verlor er alles, was ihm wichtig war – seine Familie und schließlich auch sich selbst!"}]'::jsonb, ''),
  ('du-zuapuudade-huanschlaumpn', 'Du zuapuudade Huanschlaumpn!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du zugepuderte Hurenschlampe!', '[{"kategorie": "wörtlich", "text": "\"Du verfickte Hurenvotze!\"  2. \"Du durchgeficktes Hurenluder!\"  3. \"Du männergeile Hurenschlampe!\""}]'::jsonb, 'Du vafickde Huanfut!'),
  ('du-oide-duachpuudade-huanfut', 'Du oide, duachpuudade Huanfut!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du alte, durchgepuderte Hurenfut!', '[{"kategorie": "wörtlich", "text": "\"Du alte, verfickte Hurenvotze!\"  2. \"Du altes, durchgeficktes Hurenluder!\"  3. \"Du alte, männergeile Hurenschlampe!\""}]'::jsonb, ''),
  ('de-vafickde-kraxn-is-scho-wiida-im-oasch', 'De vafickde Kraxn is scho wiida im Oasch!', '', '', '', 'Wiener Mechaniker-Slang', 'Die verfickte Kraxen ist schon wieder im Arsch!', '[{"kategorie": "wörtlich", "text": "\"Die verfluchte Karre ist schon wieder kaputt!\"  2. Die verdammte Scheißkarre hat schon wieder den Geist aufgegeben!  3. Die verfluchte Schrottkiste ist schon wieder im Arsch!"}]'::jsonb, ''),
  ('des-rippal-woa-so-zoat-dass-fost-vom-knochn-gfoin-is', 'Des Rippal woa so zoat, dass fost vom Knochn gfoin is!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Das Ripperl war so zart, dass es fast vom Knochen gefallen ist!', '[{"kategorie": "wörtlich", "text": "\"Das Rippchen war so zart und butterweich - man konnte es mühelos vom Knochen lösen!\"  2. Das Ripperl war so zart - es hat sich wie von selbst vom Knochen gelöst!  3. Das Rippchen zerging förmlich auf der Zunge und fiel wie von selbst vom Knochen!"}]'::jsonb, ''),
  ('si-s-rippal-geebm', 'si s''Rippal geebm', '', '', '', 'Tod und Sterben auf Wienerisch', 'sich das Ripperl geben', '[{"kategorie": "wörtlich", "text": "\"sich einen Stich durchs Rippchen geben\""}, {"kategorie": "", "text": "Selbstmord begehen (durch Erstechen)"}, {"kategorie": "", "text": "\"sich den finalen Herzstich verpassen\""}, {"kategorie": "", "text": "\"sich mit einem Bruststich das Leben nehmen\""}]'::jsonb, 'Obsda de Kuugl oda s''Rippal gibsd, is ma wuaschd - owa brings hinta di, sunst muass I di haamdraan!'),
  ('obsda-de-kuugl-oda-s-rippal-gibsd-is-ma-wuaschd-owa-brings-hinta-di-sunst-muass-i-di-haamdraan', 'Obsda de Kuugl oda s''Rippal gibsd, is ma wuaschd - owa brings hinta di, sunst muass I di haamdraan!', '', '', '', 'Wiener Gaunersprache', 'Ob du dir die Kugel oder das Ripperl gibst, ist mir wurscht - aber bring''s hinter dich, sonst muss ich dich heimdrehen!', '[{"kategorie": "wörtlich", "text": "\"Ob du dich erschießt oder erstichst, ist mir egal - bring''s nur schnell hinter dich, sonst muss ich dich zur Strecke bringen!\"  2. Ob du dir die Rübe wegpustet oder einen herzstich verpasst, ist mir eins - aber mach schnell, sonst mach ich dich kalt!  3. Wie du gehst, ist dein Stil – aber wenn du trödelst, übernehmen wir den Abgang!"}]'::jsonb, 'si s''Rippal geebm'),
  ('de-rippaln-san-vuagschniidn-de-brauchsd-nua-no-ind-marinaad-leeng-und-daunn-aum-grueue-haun', 'De Rippaln san vuagschniidn - de brauchsd nua no ind Marinaad leeng und daunn aum Grüü haun!', '', '', '', 'Wiener Fleischhauer-Slang', 'Die Ripperln sind vorgeschnitten – die brauchst du nur noch in die Marinade legen und dann auf den Grill hauen!', '[{"kategorie": "wörtlich", "text": "\"Die Rippchen sind vorgeschnitten – die brauchst du nur noch in die Marinade legen und dann ab auf’n Grill!\"  2. Die Rippchen sind bereits zugeschnitten – du musst sie nur noch marinieren und grillen!  3. Die Ripperln sind schon hergerichtet – einfach in die Marinade schmeißen und dann ab auf’n Rost!"}]'::jsonb, ''),
  ('schweinsrippaln-san-nix-fia-zoate-soeoen-do-schneid-ma-nix-do-reissd-ma-mit-de-zaeaend', 'Schweinsrippaln san nix fia zoate Söön - do schneid ma nix, do reissd ma mit de Zäänd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Schweinsripperln sind nichts für zarte Seelen – da schneidet man nichts, da reißt man mit den Zähnen!', '[{"kategorie": "wörtlich", "text": "\"Schweinerippchen sind nichts für Feingeister – da wird nicht geschnitten, da geht’s mit den Zähnen zur Sache!\"  2. Schweinsripperln sind für Fleischfresser – da wird nicht geschnitten, sondern mit den Zähnen gerissen, gekiefelt und geschmatzt!  3. Bei Schweinerippchen heißt es nicht ''Messer und Gabel'', sondern ''Zähne und Klauen''!"}]'::jsonb, ''),
  ('rindsrippaln-san-nix-fia-zoate-soeoen-do-schneid-ma-nix-do-reissd-ma-mit-de-zaeaend', 'Rindsrippaln san nix fia zoate Söön - do schneid ma nix, do reissd ma mit de Zäänd!', '', '', '', 'Wiener Fleischhauer-Slang', 'Rindsripperln sind nichts für zarte Seelen – da schneidet man nichts, da reißt man mit den Zähnen!', '[{"kategorie": "wörtlich", "text": "\"Rinderrippchen sind nichts für Feingeister – da wird nicht geschnitten, da geht’s mit den Zähnen zur Sache!\"  2. Rindsripperln sind für Fleischfresser – da wird nicht geschnitten, sondern mit den Zähnen gerissen, gekiefelt und geschmatzt!  3. Bei Rinderrippchen heißt es nicht ''Messer und Gabel'', sondern ''Zähne und Klauen''!"}]'::jsonb, ''),
  ('a-ruige-kuugl-scheibm', 'a ruige Kuugl scheibm', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine ruhige Kugel scheiben', '[{"kategorie": "wörtlich", "text": "\"eine ruhige Kugel schieben\""}, {"kategorie": "", "text": "\"es langsam angehen lassen\""}, {"kategorie": "", "text": "\"die Arbeit schlafen lassen\""}]'::jsonb, 'Wia hackln uns deppad, und dea scheibd wiida moi a ruige Kuugl!'),
  ('wia-hackln-uns-deppad-und-dea-scheibd-wiida-moi-a-ruige-kuugl', 'Wia hackln uns deppad, und dea scheibd wiida moi a ruige Kuugl!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wir hackeln uns deppert, und der schiebt wieder mal ''ne ruhige Kugel!', '[{"kategorie": "wörtlich", "text": "\"Wir schuften uns zu Tode, und der schiebt wieder mal ''ne ruhige Kugel!\"  2. Wir reißen uns den Arsch auf, und der liegt wieder mal auf der faulen Haut!  3. Wir hackeln wie die Blöden, und der lässt die Arbeit wieder mal schleifen!"}]'::jsonb, 'a ruige Kuugl scheibm'),
  ('kuugln-scheibm', 'Kuugln scheibm', '', '', '', 'Wiener Sprüche, die sitzen!', 'Kugeln schieben', '[{"kategorie": "", "text": "mit Glaskugeln spielen"}, {"kategorie": "", "text": "Murmelkugeln werfen"}]'::jsonb, 'Ois Kinda hauma schdundnlaung Kuugln gscheibd - gaunz oone Händy!'),
  ('ois-kinda-hauma-schdundnlaung-kuugln-gscheibd-gaunz-oone-haendy', 'Ois Kinda hauma schdundnlaung Kuugln gscheibd - gaunz oone Händy!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Als Kinder haben wir stundenlang Kugeln gerollt - ganz ohne Handy!', '[{"kategorie": "wörtlich", "text": "\"Als Kinder haben wir stundenlang Murmeln geworfen - ganz ohne Handy!\"  2. Früher, als Kinder, haben wir stundenlang mit Murmeln gespielt – da war von Handy noch keine Rede!  3. Damals, als Kinder, verbrachten wir die Nachmittage draußen beim Murmelspielen, und nicht am Handy!"}]'::jsonb, 'Kuugln scheibm'),
  ('si-de-kuugl-geebm', 'si de Kuugl geebm', '', '', '', 'Tod und Sterben auf Wienerisch', 'sich die Kugel geben', '[{"kategorie": "wörtlich", "text": "\"sich erschießen\""}, {"kategorie": "", "text": "\"Selbstmord begehen (durch Erschießen)\""}, {"kategorie": "", "text": "\"sich die Rübe wegpusten\""}, {"kategorie": "", "text": "\"sich mit einem Kopfschuss das Leben nehmen\""}]'::jsonb, 'Waunn sei Oide iwanoosad, dassa fremdpuudad, kaunna si glei de Kuugl geebm!'),
  ('waunn-sei-oide-iwanoosad-dassa-fremdpuudad-kaunna-si-glei-de-kuugl-geebm', 'Waunn sei Oide iwanoosad, dassa fremdpuudad, kaunna si glei de Kuugl geebm!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn seine Alte übernasert, dass er fremdpudert, kann er sich gleich die Kugel geben!', '[{"kategorie": "wörtlich", "text": "\"Wenn seine Alte mitbekommt, dass er fremdgeht, kann er sich gleich die Kugel geben!\"  2. Wenn seine bessere Hälfte spitzkriegt, dass er sie betrügt, kann er sich gleich die Rübe wegpusten!  3. Wenn seine Frau dahinterkommt, dass er fremdgeht, kann er sich gleich selbst erschießen!"}]'::jsonb, ''),
  ('si-ins-hangal-schmeissn', 'si ins Hangal schmeissn', '', '', '', 'Tod und Sterben auf Wienerisch', 'sich ins Hangerl schmeißen', '[{"kategorie": "wörtlich", "text": "\"sich ins Tuch werfen\" (von [[Hangerl]]=\"Tuch\")"}, {"kategorie": "scherzhaft für", "text": "sich erhängen,  sich das Leben nehmen, Selbstmord begehen (durch Erhängen), [[si ins Pendl haun]], [[de Säubaun zum Himmä neema]]"}]'::jsonb, 'si ins Pendl haun'),
  ('da-schuali-hod-si-ins-hangal-gschmissn-dea-woa-featich-mit-da-woeoed', 'Da Schuali hod si ins Hangal gschmissn - dea woa featich mit da Wööd!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Schurli hat sich ins Hangerl geschmissen - der war fertig mit der Welt!', '[{"kategorie": "wörtlich", "text": "\"Der Georg hat sich erhängt – er war fertig mit dieser Welt!\"  2. Der Schurli hat die Seilbahn in den Himmel genommen – er konnte einfach nicht mehr!  3. Der Schorschi hat sich aufgehängt – er war komplett durch mit der Welt!"}]'::jsonb, 'si ins Hangal schmeissn'),
  ('si-in-liachthof-haun', 'si in Liachthof haun', '', '', '', 'Tod und Sterben auf Wienerisch', 'sich in den Lichthof hauen', '[{"kategorie": "wörtlich", "text": "\"Selbstmord durch einen Fenstersprung in den Innenhof begehen\""}, {"kategorie": "", "text": "\"sich das Leben nehmen\""}, {"kategorie": "", "text": "\"in die ewigen Jagdgründe abreiten\""}]'::jsonb, 'Da Gustl hod si in Liachthof ghaud - und kaana waass, warum!'),
  ('da-gustl-hod-si-in-liachthof-ghaud-und-kaana-waass-warum', 'Da Gustl hod si in Liachthof ghaud - und kaana waass, warum!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Gustl hat sich in den Lichthof gehaut - und keiner weiß, warum!', '[{"kategorie": "wörtlich", "text": "\"Der Gustav hat Selbstmord begangen - er hat sich aus dem Fenster in den Innenhof gestürzt, und keiner weiß, warum!\"  2. Der Gustav hat sich das Leben genommen – er hat sich aus dem Fenster in den Innenhof gestürzt, und niemand kennt den Grund dafür!  3. Der Gustav hat seinem Leben ein Ende gesetzt – er hat sich in den Lichthof gestürzt, und keiner weiß, was ihn dazu getrieben hat!"}]'::jsonb, 'si in Liachthof haun'),
  ('von-da-donaubruckn-hupfn', 'von da Donaubruckn hupfn', '', '', '', 'Tod und Sterben auf Wienerisch', 'von der Donaubrücke hüpfen', '[{"kategorie": "wörtlich", "text": "\"Selbstmord durch einen Sprung von der Donaubrücke begehen\""}, {"kategorie": "", "text": "\"sich das Leben nehmen\""}, {"kategorie": "", "text": "\"in die ewigen Jagdgründe abtauchen\""}]'::jsonb, 'Wia eam sei Oide valossn hod, woida scho von da Donaubruckn hupfn!'),
  ('wia-eam-sei-oide-valossn-hod-woida-scho-von-da-donaubruckn-hupfn', 'Wia eam sei Oide valossn hod, woida scho von da Donaubruckn hupfn!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Als ihn seine Alte verließ, wollt er schon von der Donaubrücke hüpfen!', '[{"kategorie": "wörtlich", "text": "\"Als ihn seine Frau verließ, stand er schon auf der Donaubrücke und wollte Selbstmord begehen!\"  2. Als seine Frau ihn verließ, dachte er daran, von der Donaubrücke zu springen - und fast wäre er wirklich in die ewigen Jagdgründe abgetaucht!  3. Wie ihn seine Alte abserviert hat, ist er direkt auf die Donaubrücke gestapft – kurz davor, seinem Leben ein Ende zu setzen!"}]'::jsonb, 'von da Donaubruckn hupfn'),
  ('waunn-mi-da-gwigwi-ruafd-daunn-soog-i-eam-i-muass-no-scheissn-owa-des-kaunn-dauan', 'Waunn mi da Gwigwi ruafd, daunn soog I eam: ''I muass no scheissn - owa des kaunn dauan!''', '', '', '', 'Tod und Sterben auf Wienerisch', 'Wenn mich der Quiqui ruft, dann sag ich ihm: ''Ich muss noch scheißen - aber das kann dauern!', '[{"kategorie": "wörtlich", "text": "\"Wenn mich der Tod zu sich ruft, dann ruf ich zurück: ''Ich muss noch scheißen – aber das kann dauern''!\"  2. Wenn der Tod an meine Türe klopft, kriegt er nur ''nen Zettel: ''Bin scheißen. Kann dauern!''  3. Wenn mich der Tod ruft, werd ich ihm sagen: ''Bin leider auf’m Thron - das kann noch dauern!''"}]'::jsonb, ''),
  ('da-gwigwi-woid-mi-schoo-vueuele-moole-mitneema-owa-i-hob-eam-jeeds-moi-untan-tisch-gsoffn', 'Da Gwigwi woid mi schoo vüüle Moole mitneema - owa I hob eam jeeds Moi untan Tisch gsoffn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der Quiqui wollte mich schon viele Male mitnehmen - aber ich hab ihn jedes Mal unter den Tisch gesoffen!', '[{"kategorie": "wörtlich", "text": "\"Der Tod stand schon viele Male mit der Sense vor mir - aber ich hab ihn jedes Mal unter den Tisch gesoffen!\"  2. Der Sensenmann stand schon oft vor meiner Tür – ich hab ihm aber jedes Mal so viel Schnaps eingeschenkt, dass er vergessen hat, warum er da ist!  3. Gevatter Tod wollte mich schon oft drannehmen - aber inzwischen dürfte er kapiert haben, dass ich eine Leber aus Beton habe!"}]'::jsonb, ''),
  ('si-de-eadaepfaen-von-unt-auschaun', 'si de Eadäpfän von unt auschaun', '', '', '', 'Tod und Sterben auf Wienerisch', 'sich die Erdäpfel von unten anschauen', '[{"kategorie": "wörtlich", "text": "\"sich die Kartoffel von unten anschauen\""}, {"kategorie": "fig.", "text": "\"unter der Erde liegen\""}, {"kategorie": "", "text": "[[de Ruabm von unt zöön]]"}, {"kategorie": "", "text": "[[de Wiama fiadan]]"}]'::jsonb, 'Seit si da Hansl de Eadäpfän von unt auschaud, hod de Saufrunde aun Nivoo dazuagwunna!'),
  ('seit-si-da-hansl-de-eadaepfaen-von-unt-auschaud-hod-de-saufrunde-aun-nivoo-dazuagwunna', 'Seit si da Hansl de Eadäpfän von unt auschaud, hod de Saufrunde aun Nivoo dazuagwunna!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Seit sich der Hansi die Erdäpfeln von unten ansieht, hat die Saufrunde an Niveau dazugewonnen!', '[{"kategorie": "wörtlich", "text": "\"Seit der Hans unter der Erde liegt, hat die Saufrunde an Niveau dazugewonnen!\"  2. Seit der Hansi unter’m Rasen wohnt, ist die Stammtischrunde niveauvoller geworden!  3. Seit der Hans ins Gras gebissen hat, geht''s beim Saufen zivilisierter zu!"}]'::jsonb, ''),
  ('si-de-eapfaen-von-unt-auschaun', 'si de Eapfän von unt auschaun', '', '', '', 'Tod und Sterben auf Wienerisch', 'sich die Erpfeln von unten anschauen', '[{"kategorie": "wörtlich", "text": "\"sich die Erdäpfel von unten anschauen\""}, {"kategorie": "fig.", "text": "\"unter der Erde liegen\""}, {"kategorie": "", "text": "[[de Ruabm von unt zöön]]"}, {"kategorie": "", "text": "à\"de Wiama fiadan"}]'::jsonb, 'Wea si de Eapfän von unt auschau muass, dem is de Wööd iwan Kopf gwochsn!'),
  ('wea-si-de-eapfaen-von-unt-auschau-muass-dem-is-de-woeoed-iwan-kopf-gwochsn', 'Wea si de Eapfän von unt auschau muass, dem is de Wööd iwan Kopf gwochsn!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Wer sich die Erpfeln von unten anschauen muss, dem ist die Welt über den Kopf gewachsen!', '[{"kategorie": "wörtlich", "text": "\"Wer sich die Erdäpfeln von unten anschauen muss, dem ist die Welt im wahresten Sinn des Wortes über den Kopf gewachsen!\"  2. Wer die Rüben von unten zählt, dem ist die Welt nicht nur über den Kopf gewachsen – sie liegt jetzt wortwörtlich auf ihm!  3. Wer sich die Radieschen von unten ansehen muss, dem ist das Leben über den Kopf gewachsen – im wahrsten Sinn des Wortes!"}]'::jsonb, 'si de Eadäpfän von unt auschaun'),
  ('si-in-hoizpuedschaama-haun', 'si in Hoizpüdschaama haun', '', '', '', 'Tod und Sterben auf Wienerisch', 'sich in den Holzpyjama hauen', '[{"kategorie": "wörtlich", "text": "\"sich ins allerletzte Nachtgewand werfen\""}, {"kategorie": "", "text": "\"sich in die Holzkiste schmeißen\""}, {"kategorie": "", "text": "\"sich zur ewigen Ruhe in den Holzsarg legen\""}, {"kategorie": "", "text": "sterben, [[maukas]] gehen, [[ein]] Bankerl reißen, [[die]] Patschen strecken"}]'::jsonb, ''),
  ('waunns-leebm-noochn-tood-nua-aus-saufn-und-puudan-bschdee-daed-hauad-i-mi-jetza-scho-in-mein-hoizpuedschaama', 'Waunns Leebm noochn Tood nua aus Saufn und Puudan bschdee däd, hauad I mi jetza scho in mein Hoizpüdschaama!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Wenn das Leben nach dem Tod nur aus Saufen und Pudern bestehen täte, würde ich mich jetzt schon in meinen Holzpyjama hauen!', '[{"kategorie": "wörtlich", "text": "\"Bestünde das Leben nach dem Tod nur aus Saufen und Vögeln, würde ich mich jetzt schon in meinen Holzsarg schmeißen!\"  2. Wenn das Jenseits wie ein Puff mit Zapfhahn ist – dann lasst mich jetzt gleich in die Holzkiste hüpfen!  3. Wenn man im Jenseits nur Saufen und Pudern kennt, dann spring ich freiwiwillig in meinen Holzpyjama!"}]'::jsonb, ''),
  ('bis-zum-hoizpuedschaama', 'bis zum Hoizpüdschaama', '', '', '', 'Tod und Sterben auf Wienerisch', 'bis zum Holzpyjama', '[{"kategorie": "wörtlich", "text": "\"bis zum Anlegen des letzten Nachtgewands aus Holz\""}, {"kategorie": "", "text": "\"bis zum bitteren Ende\""}, {"kategorie": "", "text": "\"bis zum ewigen Schlaf im Holzgewand\""}, {"kategorie": "", "text": "\"bis zur ewigen Ruhe\""}]'::jsonb, 'Ea hod gsoffn, gfressn und gsuudad - und des in aana Tua bis zum Hoizpüdschaama!'),
  ('ea-hod-gsoffn-gfressn-und-gsuudad-und-des-in-aana-tua-bis-zum-hoizpuedschaama', 'Ea hod gsoffn, gfressn und gsuudad - und des in aana Tua bis zum Hoizpüdschaama!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Er hat gesoffen, gefressen und gesudert – und das in einer Tour bis zum Holzpyjama!', '[{"kategorie": "wörtlich", "text": "\"Er hat gesoffen, gefressen und gesudert – und das ohne Unterlass bis zur Kiste!\"  2. Er hat gefressen wie ein Eber, gesoffen wie ein Loch und gemeckert wie ein alter Esel – bis sie ihn im Holzanzug eingewickelt haben!  3. Er hat sich durchs Leben gesoffen, gefressen und gesudert –  – durchgehend bis hinein in den Holzpyjama!"}]'::jsonb, 'bis zum Hoizpüdschaama'),
  ('schloofn-kaunnst-im-hoizpuedschaama', 'Schloofn kaunnst im Hoizpüdschaama!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Schlafen kannst du im Holzpyjama!', '[{"kategorie": "wörtlich", "text": "\"Schlafen kannst du, wenn du in der Kiste liegst!\"  2. \"Schlafen kannst du, wenn du tot bist!  3. Wenn du horizontale Dauerruhe willst – der Friedhof ist gleich ums Eck!  4. Schlaf ist was für Tote – Lebende haben zu tun!"}]'::jsonb, ''),
  ('ind-kistn-hupfn', 'ind Kistn hupfn', '', '', '', 'Tod und Sterben auf Wienerisch', 'in die Kiste hüpfen', '[{"kategorie": "wörtlich", "text": "\"in die Totenkiste hüpfen\""}, {"kategorie": "scherzhaft für", "text": "\"in den Sarg hüpfen\", sterben, das Zeitliche segnen, [[ins]] Groos beissn, [[in]] Leffä ogeem, [[a]] Bankal reissn, [[si]] in Hoizpüdschaama haun"}]'::jsonb, 'Ind Kistn hupfn is ned schwea - owa aussehupfn umso mea!'),
  ('ind-kistn-hupfn-is-ned-schwea-owa-aussehupfn-umso-mea', 'Ind Kistn hupfn is ned schwea - owa aussehupfn umso mea!', '', '', '', 'Tod und Sterben auf Wienerisch', 'In die Kiste hüpfen ist nicht schwer - aber rauszuhüfen umso mehr!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Den Holzpyjama anzieh''n ist nicht schwer - nur rauszuhüpfen umso mehr!\"  2. In die Kiste hüpfst du schneller, als dir lieb ist - aber raus hat''s noch keiner geschafft!  3. Wer einmal ruht, der ruht für immer!"}]'::jsonb, ''),
  ('mit-wem-ind-kistn-hupfn', 'mit wem ind Kistn hupfn', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'mit jemandem in die Kiste hüpfen', '[{"kategorie": "wörtlich", "text": "\"mit jemandem ins Bett hüpfen\""}, {"kategorie": "", "text": "\"mit jemandem Sex haben\""}, {"kategorie": "", "text": "[[mit]] wem ind Haapfn schdeing"}]'::jsonb, 'Loss uns mitnaund ind Kistn hupfn - nääha kennanleanan kemma uns daunn imma noo!'),
  ('loss-uns-mitnaund-ind-kistn-hupfn-naeaeha-kennanleanan-kemma-uns-daunn-imma-noo', 'Loss uns mitnaund ind Kistn hupfn - nääha kennanleanan kemma uns daunn imma noo!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Lass uns miteinander in die Kiste hüpfen - näher kennenlernen können wir uns dann immer noch!', '[{"kategorie": "wörtlich", "text": "\"Springen wir erst mal mitsammen ins Bett – das Zwischenmenschliche ergibt sich dann von allein!\"  2. Lass uns erst mal vögeln – näher kennenlernen können wir uns danach immer noch!  3. Lass uns erst bumsen – das Reden heben wir uns für nach dem Orgasmus auf!"}]'::jsonb, 'mit wem ind Kistn hupfn'),
  ('waunn-de-glockn-leit-muass-jeeda-in-schdifd-niidaleeng', 'Waunn de Glockn leit, muass jeeda in Schdifd niidaleeng!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn die Glocke läutet, muss jeder den Stift niederlegen!', '[{"kategorie": "wörtlich", "text": "\"Sobald die Glocke ertönt, müssen alle Stifte weggelegt werden!\"  2. Wenn die Glocke läutet, ist Schluss mit lustig – dann heit''s Stift hinlegen!  3. Wenn''s bimmelt, ist die Zeit um, und der Stift bleibt liegen!"}]'::jsonb, ''),
  ('an-kraunz-niidaleeng', 'an Kraunz niidaleeng', '', '', '', 'Tod und Sterben auf Wienerisch', 'einen Kranz niederlegen', '[{"kategorie": "wörtlich", "text": "\"einen Kranz zum Gedenken niederlegen\""}, {"kategorie": "", "text": "\"einen Trauerkranz niederlegen\""}, {"kategorie": "", "text": "\"eine Kranzniederlegung vornehmen\""}]'::jsonb, 'Si haum an Kraunz fian Wiatn niidagleegd - auf da Schleifn is gschdaundn: ''Fia imma nüchtan''!'),
  ('si-haum-an-kraunz-fian-wiatn-niidagleegd-auf-da-schleifn-is-gschdaundn-fia-imma-nuechtan', 'Si haum an Kraunz fian Wiatn niidagleegd - auf da Schleifn is gschdaundn: ''Fia imma nüchtan''!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Sie haben einen Kranz für den Wirten niedergelegt - auf der Schleife ist gestanden: ''Für immer nüchtern''!', '[{"kategorie": "wörtlich", "text": "\"Zum Abschied vom Wirt legten sie einen Kranz nieder – auf der Schleife stand: ''Für immer nüchtern''!\"  2. Für den toten Wirt gab’s einen Kranz – Schleifentext: ''Endlich nüchtern''!\"  3. Sie ehrten den Wirten mit einem Kranz – auf dem Band stand: ''Dein letzter Absacker''!\""}]'::jsonb, 'an Kraunz niidaleeng'),
  ('de-hackla-leeng-de-oaweid-niida-und-de-bonzn-iare-amtln-owa-waunn-wiad-de-menschheid-de-woffn-niidaleeng', 'De Hackla leeng de Oaweid niida und de Bonzn iare Amtln - owa waunn wiad de Menschheid de Woffn niidaleeng?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Hackler legen die Arbeit nieder und die Bonzen ihre Ämter - aber wann wird die Menschheit die Waffen niederlegen?', '[{"kategorie": "wörtlich", "text": "\"Die Malocher lassen die Werkzeuge ruhen und die Eliten räumen ihre Posten – doch wann legt die Menschheit endlich die Waffen aus der Hand?\"  2. Arbeiter streiken, Politiker treten zurück – aber wann beendet die Menschheit endlich das Morden?  3. Die Werktätigen legen die Arbeit nieder, die Mächtigen geben ihre Ämter auf – doch wann lässt die Menschheit endlich das Töten sein?"}]'::jsonb, ''),
  ('de-reegln-wia-ma-im-kloosta-z-leebm-hod-san-eastmois-im-12-joahundad-schriftlich-niidagleegd-wuan', 'De Reegln, wia ma im Kloosta z''leebm hod, san eastmois im 12. Joahundad schriftlich niidagleegd wuan!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Die Regeln, wie man im Kloster zu leben hat, sind erstmals im 12. Jahrhundert schriftlich niedergelegt worden!', '[{"kategorie": "wörtlich", "text": "\"Die Regeln des Klosterlebens wurden im 12. Jahrhundert erstmals schriftlich niedergelegt!\"  2. Die klösterlichen Lebensregeln wurden erstmalsim 12. Jahrhundert schriftlich dokumentiert!  3. Die ersten schriftlichen Aufzeichnungen über die Regeln des klösterlichen Lebens stammen aus dem 12. Jahrhundert!"}]'::jsonb, ''),
  ('dea-hod-auf-olle-kompliizn-niidagleegd', 'Dea hod auf olle Kompliizn niidagleegd!', '', '', '', 'Wiener Gaunersprache', 'Der hat auf alle Komplizen niedergelegt!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Er hat ein umfassendes Geständnis abgelegt und alle Komplizen mit hochgehen lassen!\"  2. \"Der hat gesungen wie ein Vogel und auch alle Mittäter verraten!\"  3. \"Der hat bei der Polizei voll ausgepackt und auch gleich die ganze Bande ans Messer geliefert!"}]'::jsonb, ''),
  ('si-niidaleeng', 'si niidaleeng', '', '', '', 'Grundwortschatz Wienerisch', 'sich niederlegen', '[{"kategorie": "wörtlich", "text": "\"sich niederlegen\" (Kompositum aus dem abtrennbaren Präfix \"nieder\"=\"nach unten\" und \"legen\"=\"setzen\")"}, {"kategorie": "allg.", "text": "\"sich schlafen legen\", \"sich zur Ruhe begeben\", \"zu Bett gehen\", \"sich aufs Ohr hauen\""}, {"kategorie": "poetisch für", "text": "friedlich entschlafen, sterben, das Zeitliche segnen, [[haamgee]], [[den]] Löffel abgeben, [[ein]] Bankerl reißen, [[die]] Patschen strecken, [[sich]] die Erdäpfel von unten anschauen"}, {"kategorie": "scherzhaft für", "text": "\"sich vor Erstaunen/Schreck/Überforderung hinlegen müssen\", \"aus allen Wolken fallen\", \"vor Schreck in die Knie gehen\", \"den Boden unter den Füßen verlieren\", \"nicht mehr wissen, wo oben und unten ist\""}]'::jsonb, 'I leeg mi jetzd niida - weckds mi in drei Joa wiida auf!'),
  ('i-leeg-mi-jetzd-niida-weckds-mi-in-drei-joa-wiida-auf', 'I leeg mi jetzd niida - weckds mi in drei Joa wiida auf!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich lege mich jetzt nieder - weckt mich in drei Jahren wieder auf!', '[{"kategorie": "wörtlich", "text": "\"Ich begebe mich jetzt zur Ruhe - weckt mich frühestens in drei Jahren wieder auf!\"  2. Ich lege mich nieder, denn diese Welt ist mir zu laut. Weckt mich, wenn sie leiser geworden ist!  3. Ich geh jetzt offline – schaltet mich bitte erst in drei Jahren wieder ein!"}]'::jsonb, 'si niidaleeng'),
  ('in-da-nocht-zum-suundoog-hod-si-unsa-liawe-tant-luiis-fia-imma-niidagleegd', 'In da Nocht zum Suundoog hod si unsa liawe Tant Luiis fia imma niidagleegd!', '', '', '', 'Tod und Sterben auf Wienerisch', 'In der Nacht zum Sonntag hat sich unsere liebe Tante Luise für immer niedergelegt!', '[{"kategorie": "wörtlich", "text": "\"In der Nacht zum Sonntag ist unsere liebe Tante Luise friedlich entschlafen!\"  2. In der Nacht zum Sonntag hat sich unsere liebe Tante Luise zur letzten Ruhe begeben!  3. Tante Luise ist in der Nacht zum Sonntag heimgegangen - sie hat sich zur letzten Ruhe gelegt!"}]'::jsonb, 'si niidaleeng'),
  ('do-leegsd-di-niida-und-schdeesd-nimma-auf', 'Do leegsd di niida und schdeesd nimma auf!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Da legst dich nieder und stehst nimmer auf!', '[{"kategorie": "wörtlich, Ausdruck der Fassungslosigkeit", "text": "\"Da fällst du um und stehst nimmer auf!\"  2. Das haut dir den Boden unter den Füßen weg!  3. Da fällt dir die Kinnlade bis zum Boden!  4. Da bleibt dir echt die Luft weg!  5. Das ist ja der helle Wahnsinn!  6. Da muss man sich vor Schreck erstmal setzen!  7. Das darf doch nicht wahr sein!  8. [[Heilige]] Scheiße!"}]'::jsonb, 'si niidaleeng'),
  ('min-aanasiibzga-haamfoan', 'min Aanasiibzga haamfoan', '', '', '', 'Tod und Sterben auf Wienerisch', 'mit dem 71-er heimfahren', '[{"kategorie": "wörtlich", "text": "\"mit der Straßenbahnlinie 71 fahren\" (Die Straßenbahnlinie 71 fährt seit Anfang des 20. Jahrhunderts direkt zum Wiener Zentralfriedhof, einem der größten Friedhöfe Europas. Für viele Menschen – besonders früher – war der 71er der übliche Weg zur Beerdigung: Angehörige, Trauergäste, aber auch Leichenzüge nutzten die Linie, um zum Friedhof zu gelangen)"}, {"kategorie": "scherzhaft für", "text": "sterben, den letzten Weg antreten, das Zeitliche segnen, [[ein]] Bankerl reißen, [[die]] Patschen strecken, [[die]] Eisen aufstellen"}]'::jsonb, 'Waunnsd ned glei de Goschn hoidsd, foasd min Aanasiibzga haam!'),
  ('waunnsd-ned-glei-de-goschn-hoidsd-foasd-min-aanasiibzga-haam', 'Waunnsd ned glei de Goschn hoidsd, foasd min Aanasiibzga haam!', '', '', '', 'Wiener Gaunersprache', 'Wenn du nicht gleich die Gosch''n hältst, fährst du mit dem 71-er heim!', '[{"kategorie": "wörtlich", "text": "\"Wenn du nicht sofort die Klappe hältst, fährst du mit dem 71-er heim!\" (Die Straßenbahnlinie 71 fährt seit Anfang des 20. Jahrhunderts direkt zum Wiener Zentralfriedhof, einem der größten Friedhöfe Europas. Für viele Menschen – besonders früher – war der 71er der übliche Weg zur Beerdigung: Angehörige, Trauergäste, aber auch Leichenzüge nutzten die Linie, um zum Friedhof zu gelangen)"}, {"kategorie": "Gaunersprache", "text": "\"Wenn du nicht sofort den Mund hältst, kriegsd ''nen Gratis-Fahrschein für''n 71-er, kapische?\"  3. \"Noch ein Ton, und ich sorge dafür, dass du nichts mehr zu sagen hast – dann geht''s für dich mit''m 71-er heim, für immer!\""}]'::jsonb, 'min Aanasiibzga haamfoan'),
  ('haamgee-tua-ma-ned-bis-dass-des-liachd-ausgeed', 'Haamgee tua ma ned, bis dass des Liachd ausgeed!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Heimgehen tun wir nicht, bis dass das Licht ausgeht!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Wir gehen erst, wenn hier das letzte Licht ausgeht!\"  2. \"Wir feiern durch, bis der Letzte umfällt!\"  3. (poetisch): Wir verlassen diese Welt erst, wenn unser inneres Licht ausgeht!  4. Heimwärts geht''s erst, wenn das Licht des Lebens in uns erlischt!"}]'::jsonb, ''),
  ('da-heagood-hod-eam-gruafn-und-ea-is-in-friidn-haamgaungan', 'Da Heagood hod eam gruafn - und ea is in Friidn haamgaungan!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Herrgott hat ihn gerufen - und er ist in Frieden heimgegangen!', '[{"kategorie": "wörtlich", "text": "\"Der Herr hat ihn zu sich gerufen – und er ist in Frieden zu ihm heimgegangen!\"  2. Er folgte dem Ruf des Herrn und ging heim in Frieden!  3. Er ging heim zum Herren, getragen vom Glauben, geführt vom Licht!"}]'::jsonb, ''),
  ('seawas-pfiat-di-gee-haam-und-daschiass-di', 'Seawas, pfiat di, gee haam und daschiass di!', '', '', '', 'Wiener Gaunersprache', 'Servus, leb wohl, geh heim und erschieß dich!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Tschüss, hau ab, und lass dich hier nie wieder blicken!\"  2. Ciao, leb wohl und machdich vom Acker – und zwar für immer!  3. Servus, zieh Leine und komm nur ja nie mehr zurück!"}]'::jsonb, 'Pfiat di!'),
  ('i-waass-si-is-a-schdrichkotz-owa-si-hod-an-bessan-karakta-ois-dei-oide', 'I waass, si is a Schdrichkotz - owa si hod an bessan Karakta ois dei Oide!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich weiß, sie ist eine Strichkatze - aber sie hat einen besseren Charakter als deine Alte!', '[{"kategorie": "wörtlich", "text": "\"Ich weiß, sie verdingt sich als Sexarbeiterin – aber im Gegensatz zu deiner Alten hat sie Stil!\"  2. \"Klar läuft sie am Strich – aber sie hat mehr Herz als deine Tussi daheim!\"  3. \"Ja, sie lebt vom Gewerbe – aber sie ist ein besserer Mensch als deine Frau je war!\""}]'::jsonb, ''),
  ('des-betthaasal-schaud-aus-wiara-engl-puudad-owa-wia-da-teifae', 'Des Betthaasal schaud aus wiara Engl - puudad owa wia da Teifä!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Das Betthaserl schaut aus wie ein Engel - pudert aber wie der Teufel!', '[{"kategorie": "wörtlich", "text": "\"Das Betthäschen sieht aus wie ein Engel - vögelt aber wie der Teufel!\"  2. Das Kätzchen sieht aus wie ein Engel – aber im Bett ist sie der reinste Höllenritt!  3. Dachte, ich lad mir ''nen Engel ein – war dann ''ne Sexmaschine mit Engelsflügeln!"}]'::jsonb, ''),
  ('des-betthaasal-vom-letzdn-wochneend-hod-eam-mea-kost-ois-sei-auto', 'Des Betthaasal vom letzdn Wochneend hod eam mea kost ois sei Auto!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Das Betthäschen vom letzten Wochenende hat ihn mehr gekostet als sein Auto!', '[{"kategorie": "wörtlich", "text": "\"Das Escort-Girl vom letzten Wochenende hat ihn mehr gekostet als sein Auto!\"  2. Das Laufmädchen, das er sich fürs ganze Wochenende gebucht hat, war teurer als sein ganzer Fuhrpark!  3. Manche investieren in Immobilien – er investiert in Betthäschen mit Wochenendpauschale!"}]'::jsonb, ''),
  ('de-schnepfn-is-a-guad-tarnta-voogl-mit-an-laungan-schbitzn-schnoowae-dea-im-sumpfign-boodn-nooch-wiama-peckd-und-bei-da-boiz-wiara-frosch-quaakd-und-zickzack-fliagd', 'De Schnepfn is a guad tarnta Voogl mit an laungan, schbitzn Schnoowä, dea im sumpfign Boodn nooch Wiama peckd und bei da Boiz wiara Frosch quaakd und zickzack fliagd!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Die Schnepfe ist ein gut getarnter Vogel mit einem langen, spitzen Schnabel, der im sumpfigen Boden nach Würmern pickt und bei der Balz wie ein Frosch quakt und zickzack fliegt!', '[{"kategorie": "wörtlich", "text": "\"Die Schnepfe ist ein gut getarnter Vogel mit langem Schnabel, der in Feuchtgebieten lebt, am Boden nach Würmern sucht und in der Dämmerung mit ruckartigem Flug und froschähnlichem Schrei balzt!\"  2. Die Schnepfe ist ein gut getarnter Watvogel mit langem Schnabel, der in Feuchtgebieten lebt, am Boden nach Würmern sucht und in der Dämmerung mit seltsamem Balzruf auffällt!  3. Die Schnepfe ist der Ninja unter den Sumpfvögeln: Meisterhaft getarnt, mit einem Rüssel zum Wurmsuchen und einem Balzverhalten, das klingt, als würde ein Frosch fliegen lernen!"}]'::jsonb, ''),
  ('de-deppade-schnepfn-mit-iare-aufgschbritzdn-botox-lippn-laestad-in-gaunzn-toog', 'De deppade Schnepfn mit iare aufgschbritzdn Botox-Lippn lästad in gaunzn Toog!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die depperte Schnepfe mit ihren aufgespritzten Botox-Lippen lästert den ganzen Tag!', '[{"kategorie": "wörtlich", "text": "\"Diese blöde Ziege lästert den ganzen Tag über andere rum und glaubt, ihre Collagen-Lippen machen sie zur Diva!\"  2. Diese hohle Tussi lästert den ganzen Tag über andere rum – und das mit ’ner Fresse wie’n Gummiboot!  3. Diese unausstehliche Zimtzicke mit ihren aufgespritzten Botox-Lippen spuckt den ganzen Tag nur Gift und Galle!"}]'::jsonb, ''),
  ('de-schnepfn-hod-mea-kilomaeaeta-auf-da-ua-ois-mei-oida-oopae', 'De Schnepfn hod mea Kilomääta auf da Ua ois mei oida Oopä!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die Schnepfe hat mehr Kilometer auf der Uhr als mein alter Opel!', '[{"kategorie": "wörtlich", "text": "\"Die Schnepfe hat mehr Kilometer auf der Uhr als mein Opel!\"  2. Diese Asphaltschwalbe ist öfter geritten worden als mein alter Opel-Kombi!  3. Die Alte vom Straßenstrich hat mehr Rücksitze gesehen als mein alter Opel in seinem ganzen Leben!"}]'::jsonb, ''),
  ('fian-kaisa-hods-zum-fruaschduck-imma-schnepfnbrood-geebm-auf-an-frisch-greesdn-laundbrood-reichlich-beschdrichn-mid-schnepfndreck', 'Fian Kaisa hods zum Fruaschduck imma Schnepfnbrood geebm - auf an frisch greesdn Laundbrood, reichlich beschdrichn mid Schnepfndreck!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Für den Kaiser hat''s zum Frühstück immer Schnepfenbrot gegeben - auf einem frisch gerösteten Landbrot, reichlich bestrichen mit Schnepfendreck!', '[{"kategorie": "wörtlich", "text": "\"Dem Kaiser wurde allmorgendlich Schnepfenbrot gereicht – auf ofenwarmem Bauernlaib, dick bestrichen mit der dunklen Wildfarce der Schnepfe!\"  2. Kein Frühstück am Hof, ohne das traditionelle Schnepfenbrot – frisch geröstetes Brot, üppig belegt mit der kräftigen Farce aus den Innereien der Schnepfe!  3. Zum kaiserlichen Frühstück gehörte stets auch Schnepfenbrot: frisch geröstetes Landbrot, großzügig bestrichen mit der aromatischen Farce – im Volksmund als Schnepfendreck verspottet!"}]'::jsonb, ''),
  ('da-schnepfnschdrich-is-da-boizfluug-von-de-woidschnepfn-mandaln', 'Da Schnepfnschdrich is da Boizfluug von de Woidschnepfn-Mandaln!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Der Schnepfenstrich ist der Balzflug der Waldschnepfen-Männchen!', '[{"kategorie": "wörtlich", "text": "\"Als ''Schnepfenstrich'' bezeichnet man den Balzflug der männlichen Waldschnepfen!\"  2. Der Begriff ‚Schnepfenstrich‘ beschreibt den charakteristischen Balzflug männlicher Waldschnepfen!  3. In der Ornithologie steht der Begriff ‚Schnepfenstrich‘ für das Balzverhalten der männlichen Waldschnepfe während der Paarungszeit!  4. ‚Schnepfenstrich‘ – so nennt man jenen geheimnisvollen Dämmerungsflug, mit dem die männliche Waldschnepfe um die Gunst des Weibchens wirbt!"}]'::jsonb, ''),
  ('de-kiiwara-kennan-a-jeeds-betthaasal-vom-schnepfnschdrich-beim-nauman', 'De Kiiwara kennan a jeeds Betthaasal vom Schnepfnschdrich beim Nauman!', '', '', '', 'Wiener Gaunersprache', 'Die Kieberer kennen jedes Betthaserl vom Schnepfenstrich beim Namen!', '[{"kategorie": "wörtlich", "text": "\"\"Die Bullen kennen jedes Betthäschen vom Straßenstrich beim Namen!\"  2. Die Polizisten kennen jedes Mädel vom Asphaltrevier beim Namen!  3. Die Kriminalbeamten haben jede Nachtschwalbe aus dem Rotlichtrevier längst auf dem Radar!"}]'::jsonb, ''),
  ('meine-uarlis-leebm-olle-zwaa-no', 'Meine Uarlis leebm olle zwaa no!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Meine Urlis leben alle zwei noch!', '[{"kategorie": "wörtlich", "text": "\"Meine Urgroßeltern leben beide noch!\"  2. Ich habe das große Glück, dass meine Urgroßeltern beide noch am Leben sind!  3. Meine Ururoma und mein Ururopa leben beide noch – und ich sehe sie regelmäßig!"}]'::jsonb, ''),
